    fn invoke_authorities(
        deny_command: bool,
        program_links: ProgramLinkTrace,
    ) -> Arc<ScopedHostService> {
        let security = Arc::new(CommandSecurityAuthority {
            descriptor: descriptor("host.security.authorize"),
            deny_command,
            deny_transform: false,
            deny_journal: false,

            deny_event: false,
            deny_counter: false,
            deny_diagnostic: false,
            deny_web: false,
            deny_dataset: false,
            deny_surrogate: false,
            principal_decision: SecurityDecision::Allow,
            seen: Arc::new(Mutex::new(Vec::new())),
        }) as Arc<dyn HostProvider>;
        let programs = Arc::new(TracedProgramAuthority {
            descriptor: descriptor("host.program.invoke"),
            seen: program_links,
        }) as Arc<dyn HostProvider>;
        Arc::new(ScopedHostService::new(
            Arc::new(
                RegistrySnapshot::new(1, vec![security, programs], InvocationLimits::default())
                    .unwrap(),
            ),
            HostLimits::default(),
        ))
    }

    fn start_authorities(
        deny_surrogate: bool,
        principal_decision: SecurityDecision,
    ) -> (Arc<ScopedHostService>, CommandSecurityTrace) {
        let seen = Arc::new(Mutex::new(Vec::new()));
        let providers = vec![
            Arc::new(CommandSecurityAuthority {
                descriptor: descriptor("host.security.authorize"),
                deny_command: false,
                deny_transform: false,
                deny_journal: false,

                deny_event: false,
                deny_counter: false,
                deny_diagnostic: false,
                deny_web: false,
                deny_dataset: false,
                deny_surrogate,
                principal_decision,
                seen: seen.clone(),
            }) as Arc<dyn HostProvider>,
            Arc::new(Authority {
                descriptor: descriptor("host.clock"),
            }) as Arc<dyn HostProvider>,
        ];
        (
            Arc::new(ScopedHostService::new(
                Arc::new(RegistrySnapshot::new(1, providers, InvocationLimits::default()).unwrap()),
                HostLimits::default(),
            )),
            seen,
        )
    }

    fn traced_authorities(trace: Arc<DatasetTrace>) -> Arc<ScopedHostService> {
        let mut providers = [
            "host.security.authorize",
            "host.program.invoke",
            "host.clock",
        ]
        .into_iter()
        .map(|capability| {
            Arc::new(Authority {
                descriptor: descriptor(capability),
            }) as Arc<dyn HostProvider>
        })
        .collect::<Vec<_>>();
        for capability in ["host.dataset.read", "host.dataset.write"] {
            providers.push(Arc::new(TracedDataset {
                descriptor: descriptor(capability),
                trace: trace.clone(),
            }));
        }
        Arc::new(ScopedHostService::new(
            Arc::new(RegistrySnapshot::new(1, providers, InvocationLimits::default()).unwrap()),
            HostLimits::default(),
        ))
    }

    fn denied_dataset_authorities(
        trace: Arc<DatasetTrace>,
        seen: CommandSecurityTrace,
    ) -> Arc<ScopedHostService> {
        let mut providers = vec![Arc::new(CommandSecurityAuthority {
            descriptor: descriptor("host.security.authorize"),
            deny_command: false,
            deny_transform: false,
            deny_journal: false,

            deny_event: false,
            deny_counter: false,
            deny_diagnostic: false,
            deny_web: false,
            deny_dataset: true,
            deny_surrogate: false,
            principal_decision: SecurityDecision::Allow,
            seen,
        }) as Arc<dyn HostProvider>];
        for capability in ["host.dataset.read", "host.dataset.write"] {
            providers.push(Arc::new(TracedDataset {
                descriptor: descriptor(capability),
                trace: trace.clone(),
            }));
        }
        Arc::new(ScopedHostService::new(
            Arc::new(RegistrySnapshot::new(1, providers, InvocationLimits::default()).unwrap()),
            HostLimits::default(),
        ))
    }

