    fn writeq_request(
        queue_argument: &str,
        queue: &[u8],
        value: &[u8],
        length: i64,
        sequence: u64,
    ) -> CicsRequest {
        request(
            CicsOperation::WriteTemporaryStorage,
            BTreeMap::from([
                (queue_argument.into(), cics_literal(queue)),
                ("FROM".into(), task_value(value)),
                ("LENGTH".into(), cics_decimal(length)),
            ]),
            sequence,
        )
    }

    fn responding(mut request: CicsRequest) -> CicsRequest {
        request.arguments.insert("RESP".into(), argument(b"RESP-X"));
        request
            .arguments
            .insert("RESP2".into(), argument(b"RESP2-X"));
        request.condition_policy = CicsConditionPolicy::Respond {
            response_field: "RESP-X".into(),
            response2_field: Some("RESP2-X".into()),
        };
        request
    }

    fn temporary_payload(lock: u8, items: &[(&str, &[u8])]) -> Vec<u8> {
        let mut payload = b"METS1".to_vec();
        payload.extend_from_slice(&[0, lock]);
        payload.extend_from_slice(&0_u32.to_be_bytes());
        payload.extend_from_slice(&u32::try_from(items.len()).unwrap().to_be_bytes());
        for (effect_key, value) in items {
            field(&mut payload, effect_key.as_bytes()).unwrap();
            field(&mut payload, value).unwrap();
        }
        payload
    }

    fn install_program_artifact(store: &dyn ArtifactStore, bytes: &[u8]) -> (ArtifactRef, String) {
        let digest: [u8; 32] = Sha256::digest(bytes).into();
        let artifact = ArtifactRef::new(
            format!("sha256:{:x}", Sha256::digest(bytes)),
            InvocationLimits::default(),
        )
        .unwrap();
        let semantic_identity = format!(
            "semantic-sha256:{:x}",
            Sha256::digest([b"semantic", bytes].concat())
        );
        let executable = ExecutableArtifactMetadata {
            artifact_contract: "mainframe-env.artifact@3".into(),
            compatibility_profile: "mainframe-env.cobol.reference@1".into(),
            compiler_generation: "mainframe-env-cobol-test".into(),
            target: "reference".into(),
            options: BTreeMap::new(),
            host_interfaces: BTreeSet::from(["mainframe-env.cics@1".into()]),
            ir_contract: "mainframe-env.ir@1".into(),
            dialect_contracts: Some(BTreeSet::from(["mainframe-env.cobol@1".into()])),
            semantic_identity: semantic_identity.clone(),
            manifest_payload_digest: [0; 32],
        }
        .bind_to_payload(&digest);
        store
            .put_artifact(ArtifactRecord {
                artifact: artifact.clone(),
                media_type: "application/vnd.mainframe-env.core-mir".into(),
                payload_digest: digest,
                payload: bytes.to_vec(),
                executable: Some(executable),
            })
            .unwrap();
        (artifact, semantic_identity)
    }

    fn register_load_program(
        cics: &CicsService,
        store: &dyn ArtifactStore,
        name: &str,
        generation: u64,
        bytes: &[u8],
        entry_offset: u32,
    ) -> ArtifactRef {
        let (artifact, semantic_identity) = install_program_artifact(store, bytes);
        cics.register_program_definitions(&[CicsProgramDefinition {
            name: name.into(),
            generation,
            artifact: artifact.clone(),
            semantic_identity,
            entry_offset,
            enabled: true,
            remote: false,
            reload: false,
            java_status: CicsJavaStatus::NotJava,
        }])
        .unwrap();
        artifact
    }

    fn load_arguments(
        program: &str,
        hold: bool,
        fullword: bool,
    ) -> BTreeMap<String, BoundedPayload> {
        let mut arguments = BTreeMap::from([
            ("PROGRAM".into(), cics_literal(program.as_bytes())),
            ("SET".into(), argument(b"SET-X")),
            ("ENTRY".into(), argument(b"ENTRY-X")),
            ("SET.MAXLENGTH".into(), cics_decimal(1_048_576)),
            (
                if fullword { "FLENGTH" } else { "LENGTH" }.into(),
                argument(b"LENGTH-X"),
            ),
        ]);
        if hold {
            arguments.insert("OPTION.HOLD".into(), cics_option());
        }
        arguments
    }

