    fn wait_event_arguments(
        event: [u8; 4],
        posted: bool,
        name: Option<&[u8]>,
    ) -> BTreeMap<String, BoundedPayload> {
        let mut arguments = BTreeMap::from([
            (
                "ECADDR".into(),
                BoundedPayload::new(
                    "mainframe-env.cics.event-list@1",
                    event.to_vec(),
                    InvocationLimits::default(),
                )
                .unwrap(),
            ),
            (
                "EVENT.POSTED".into(),
                BoundedPayload::new(
                    "mainframe-env.cics.event-posted@1",
                    vec![u8::from(posted)],
                    InvocationLimits::default(),
                )
                .unwrap(),
            ),
        ]);
        if let Some(name) = name {
            arguments.insert("NAME".into(), cics_literal(name));
        }
        arguments
    }

    fn wait_external_arguments(
        events: &[(u32, [u8; 4])],
        selected: Option<u32>,
        count: i64,
        purgeable: bool,
    ) -> BTreeMap<String, BoundedPayload> {
        let mut list = Vec::with_capacity(events.len() * 8);
        for (index, address) in events {
            list.extend_from_slice(&index.to_be_bytes());
            list.extend_from_slice(address);
        }
        BTreeMap::from([
            (
                "ECBLIST".into(),
                BoundedPayload::new(
                    "mainframe-env.cics.external-event-list@1",
                    list,
                    InvocationLimits::default(),
                )
                .unwrap(),
            ),
            (
                "EVENT.POSTED".into(),
                BoundedPayload::new(
                    "mainframe-env.cics.event-posted-index@1",
                    selected
                        .map(|index| index.to_be_bytes().to_vec())
                        .unwrap_or_default(),
                    InvocationLimits::default(),
                )
                .unwrap(),
            ),
            ("NUMEVENTS".into(), cics_decimal(count)),
            (
                if purgeable {
                    "OPTION.PURGEABLE"
                } else {
                    "OPTION.NOTPURGEABLE"
                }
                .into(),
                cics_option(),
            ),
        ])
    }

