        let store = Arc::new(SqliteStateStore::open(&url, 4 * 1024 * 1024, 65_536).unwrap());
        let service =
            CicsService::open(authorities(), store.clone(), CicsLimits::default()).unwrap();
        let (invocation, session) = registered(&service);
