    #[test]
    fn diagnostic_configuration_survives_sqlite_reopen() {
        let root = std::env::temp_dir().join(format!(
            "mainframe-env-cics-diagnostics-{}-{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&root).unwrap();
        let url = format!("sqlite://{}?mode=rwc", root.join("state.db").display());
        let configuration = CicsTraceConfiguration {
            user_trace: false,
            internal: true,
            auxiliary: true,
            system: false,
        };
        let dump_code = CicsDumpCodeDefinition {
            code: "ABCD".into(),
            suppress: false,
            maximum: 2,
            system_dump: false,
        };
        let monitor_point = CicsMonitorPointDefinition {
            entry_name: "USER".into(),
            point: 11,
            action: CicsMonitorAction::AddCounter { slot: 1 },
        };
        {
            let store = Arc::new(SqliteStateStore::open(&url, 4 * 1024 * 1024, 65_536).unwrap());
            let service = service(store);
            service.configure_diagnostic_trace(configuration).unwrap();
            service
                .register_diagnostic_resources(&[dump_code.clone()], &[monitor_point.clone()])
                .unwrap();
            assert_eq!(service.diagnostic_snapshot().unwrap().version, 2);
        }
        {
            let store = Arc::new(SqliteStateStore::open(&url, 4 * 1024 * 1024, 65_536).unwrap());
            let service = service(store);
            let snapshot = service.diagnostic_snapshot().unwrap();
            assert_eq!(snapshot.configuration, configuration);
            assert_eq!(snapshot.dump_definitions["ABCD"], dump_code);
            assert_eq!(snapshot.monitor_definitions["USER:011"], monitor_point);
            assert!(snapshot.traces.is_empty() && snapshot.dumps.is_empty());
            service.configure_diagnostic_trace(configuration).unwrap();
            service
                .register_diagnostic_resources(&[dump_code.clone()], &[monitor_point.clone()])
                .unwrap();
            assert_eq!(service.diagnostic_snapshot().unwrap().version, 2);
        }
        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn enter_tracenum_validates_flags_bounds_and_replays_retained_bytes() {
        let store = Arc::new(MemoryStore::new(Default::default()));
        let provider: Arc<dyn ProviderStateStore> = store.clone();
        let service = service(provider);
        let (invocation, _) = registered(&service);
        let arguments = BTreeMap::from([
            ("TRACENUM".into(), cics_decimal(123)),
            ("FROM".into(), enqueue_value(b"EXAMPLE!")),
            ("FROMLENGTH".into(), cics_decimal(4)),
            ("RESOURCE".into(), cics_literal(b"PROGRAM1")),
        ]);
        let mut disabled = request(CicsOperation::EnterTraceNum, arguments.clone(), 1);
        disabled.condition_policy = CicsConditionPolicy::NoHandle;
        let result = service
            .invoke(
                &effect(&invocation.run_unit_id, disabled.clone(), 1),
                disabled,
            )
            .unwrap();
        assert_eq!(
            (result.condition.as_str(), result.response, result.response2),
            ("INVREQ", 16, 3)
        );
        assert!(service.diagnostic_snapshot().unwrap().traces.is_empty());

        let mut exception_arguments = arguments.clone();
        exception_arguments.insert("OPTION.EXCEPTION".into(), cics_option());
        let exception = request(CicsOperation::EnterTraceNum, exception_arguments, 2);
        let first = service
            .invoke(
                &effect(&invocation.run_unit_id, exception.clone(), 2),
                exception.clone(),
            )
            .unwrap();
        assert_eq!(first.condition, "NORMAL");
        let snapshot = service.diagnostic_snapshot().unwrap();
        assert_eq!(snapshot.traces.len(), 1);
        assert_eq!(snapshot.traces[0].data, b"EXAM");
        assert_eq!(snapshot.traces[0].kind, "TRACENUM:INTERNAL");
        assert!(snapshot.traces[0].exception);
        store
            .delete_provider_state("cics-effect-replay-v1", "outer-2", 1)
            .unwrap();
        let replayed = service
            .invoke(
                &effect(&invocation.run_unit_id, exception.clone(), 2),
                exception,
            )
            .unwrap();
        assert_eq!(replayed, first);
        assert_eq!(service.diagnostic_snapshot().unwrap().traces.len(), 1);

        let mut bad = request(CicsOperation::EnterTraceNum, arguments, 3);
        bad.arguments.insert("TRACENUM".into(), cics_decimal(200));
        bad.condition_policy = CicsConditionPolicy::NoHandle;
        let result = service
            .invoke(&effect(&invocation.run_unit_id, bad.clone(), 3), bad)
            .unwrap();
        assert_eq!((result.response, result.response2), (16, 1));
    }

    #[test]
    fn enter_tracenum_denial_precedes_durable_mutation() {
        let (authorities, seen) = diagnostic_authorities(true);
        let service = CicsService::open(
            authorities,
            Arc::new(MemoryStore::new(Default::default())),
            CicsLimits::default(),
        )
        .unwrap();
        let (invocation, _) = registered(&service);
        let mut denied = request(
            CicsOperation::EnterTraceNum,
            BTreeMap::from([
                ("TRACENUM".into(), cics_decimal(12)),
                ("OPTION.EXCEPTION".into(), cics_option()),
            ]),
            1,
        );
        denied.condition_policy = CicsConditionPolicy::NoHandle;
        let result = service
            .invoke(&effect(&invocation.run_unit_id, denied.clone(), 1), denied)
            .unwrap();
        assert_eq!(
            (result.condition.as_str(), result.response),
            ("NOTAUTH", 70)
        );
        assert!(service.diagnostic_snapshot().unwrap().traces.is_empty());
        assert!(
            seen.lock()
                .unwrap()
                .iter()
                .any(|(class, resource, intent)| {
                    class == "CICSDIAG"
                        && resource == "CICS.DIAG.TRACE"
                        && *intent == AccessIntent::Update
                })
        );
    }

    #[test]
    fn monitor_applies_registered_emp_and_replays_counter_update() {
        let store = Arc::new(MemoryStore::new(Default::default()));
        let provider: Arc<dyn ProviderStateStore> = store.clone();
        let service = service(provider);
        service
            .register_diagnostic_resources(
                &[],
                &[
                    CicsMonitorPointDefinition {
                        entry_name: "USER".into(),
                        point: 11,
                        action: CicsMonitorAction::AddCounter { slot: 1 },
                    },
                    CicsMonitorPointDefinition {
                        entry_name: "USER".into(),
                        point: 12,
                        action: CicsMonitorAction::Move {
                            offset: 0,
                            maximum_length: 4,
                        },
                    },
                ],
            )
            .unwrap();
        let (invocation, _) = registered(&service);
        let update = request(
            CicsOperation::Monitor,
            BTreeMap::from([
                ("POINT".into(), cics_decimal(11)),
                ("DATA1".into(), enqueue_value(&5_i32.to_be_bytes())),
            ]),
            1,
        );
        service
            .invoke(
                &effect(&invocation.run_unit_id, update.clone(), 1),
                update.clone(),
            )
            .unwrap();
        assert_eq!(
            service.diagnostic_snapshot().unwrap().monitor_counters["USER:001"],
            5
        );
        store
            .delete_provider_state("cics-effect-replay-v1", "outer-1", 1)
            .unwrap();
        service
            .invoke(&effect(&invocation.run_unit_id, update.clone(), 1), update)
            .unwrap();
        assert_eq!(
            service.diagnostic_snapshot().unwrap().monitor_counters["USER:001"],
            5
        );

        let move_request = request(
            CicsOperation::Monitor,
            BTreeMap::from([
                ("POINT".into(), cics_decimal(12)),
                ("DATA1".into(), enqueue_value(&[0, 0, 0, 1])),
                (
                    "DATA1.BYTES".into(),
                    BoundedPayload::new(
                        "mainframe-env.cics.monitor-data@1",
                        b"ABCD".to_vec(),
                        InvocationLimits::default(),
                    )
                    .unwrap(),
                ),
            ]),
            2,
        );
        let result = service
            .invoke(
                &effect(&invocation.run_unit_id, move_request.clone(), 2),
                move_request,
            )
            .unwrap_err();
        assert_eq!(
            result,
            HostProblem::Condition {
                name: "INVREQ".into(),
                response: 16,
                response2: 6
            }
        );
        assert_eq!(
            service.diagnostic_snapshot().unwrap().monitor_text["USER"],
            b"ABCD"
        );
    }

    #[test]
    fn monitor_clock_state_survives_sqlite_reopen_and_stop() {
        let root = std::env::temp_dir().join(format!(
            "mainframe-env-cics-monitor-clock-{}-{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&root).unwrap();
        let url = format!("sqlite://{}?mode=rwc", root.join("state.db").display());
        let points = [
            CicsMonitorPointDefinition {
                entry_name: "USER".into(),
                point: 20,
                action: CicsMonitorAction::StartClock { slot: 1 },
            },
            CicsMonitorPointDefinition {
                entry_name: "USER".into(),
                point: 21,
                action: CicsMonitorAction::StopClock { slot: 1 },
            },
        ];
        {
            let store = Arc::new(SqliteStateStore::open(&url, 4 * 1024 * 1024, 65_536).unwrap());
            let service = service(store);
            service.register_diagnostic_resources(&[], &points).unwrap();
            let (invocation, _) = registered(&service);
            let start = request(
                CicsOperation::Monitor,
                BTreeMap::from([("POINT".into(), cics_decimal(20))]),
                1,
            );
            service
                .invoke(&effect(&invocation.run_unit_id, start.clone(), 1), start)
                .unwrap();
            assert!(
                service
                    .diagnostic_snapshot()
                    .unwrap()
                    .monitor_clocks
                    .contains_key("USER:001")
            );
        }
        {
            let store = Arc::new(SqliteStateStore::open(&url, 4 * 1024 * 1024, 65_536).unwrap());
            let service = service(store);
            let invocation = invocation_for("monitor-reopen", BTreeMap::new());
            let session = SessionId::new("monitor-reopen", 64).unwrap();
            service.create_session(&session, 24, 80).unwrap();
            service
                .register_run(invocation.clone(), &session, "MENU", "MEAPPL", "MESYS")
                .unwrap();
            let stop = request(
                CicsOperation::Monitor,
                BTreeMap::from([("POINT".into(), cics_decimal(21))]),
                2,
            );
            service
                .invoke(&effect(&invocation.run_unit_id, stop.clone(), 2), stop)
                .unwrap();
            let snapshot = service.diagnostic_snapshot().unwrap();
            assert!(!snapshot.monitor_clocks.contains_key("USER:001"));
            assert_eq!(snapshot.monitor_counters["USER:001"], 0);
        }
        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn monitor_denial_and_invalid_point_leave_state_unchanged() {
        let (authorities, seen) = diagnostic_authorities(true);
        let service = CicsService::open(
            authorities,
            Arc::new(MemoryStore::new(Default::default())),
            CicsLimits::default(),
        )
        .unwrap();
        service
            .register_diagnostic_resources(
                &[],
                &[CicsMonitorPointDefinition {
                    entry_name: "USER".into(),
                    point: 11,
                    action: CicsMonitorAction::AddCounter { slot: 1 },
                }],
            )
            .unwrap();
        let (invocation, _) = registered(&service);
        let mut denied = request(
            CicsOperation::Monitor,
            BTreeMap::from([
                ("POINT".into(), cics_decimal(11)),
                ("DATA1".into(), enqueue_value(&5_i32.to_be_bytes())),
            ]),
            1,
        );
        denied.condition_policy = CicsConditionPolicy::NoHandle;
        let result = service
            .invoke(&effect(&invocation.run_unit_id, denied.clone(), 1), denied)
            .unwrap();
        assert_eq!(result.condition, "NOTAUTH");
        assert!(
            service
                .diagnostic_snapshot()
                .unwrap()
                .monitor_counters
                .is_empty()
        );
        assert!(
            seen.lock()
                .unwrap()
                .iter()
                .any(|(class, resource, intent)| {
                    class == "CICSDIAG"
                        && resource == "CICS.DIAG.MONITOR.USER.011"
                        && *intent == AccessIntent::Update
                })
        );
        let mut invalid = request(
            CicsOperation::Monitor,
            BTreeMap::from([("POINT".into(), cics_decimal(0))]),
            2,
        );
        invalid.condition_policy = CicsConditionPolicy::NoHandle;
        let result = service
            .invoke(
                &effect(&invocation.run_unit_id, invalid.clone(), 2),
                invalid,
            )
            .unwrap();
        assert_eq!((result.response, result.response2), (16, 1));
    }

    #[test]
    fn dump_transaction_retains_selected_bytes_and_suppresses_after_maximum() {
        let store = Arc::new(MemoryStore::new(Default::default()));
        let provider: Arc<dyn ProviderStateStore> = store.clone();
        let service = service(provider);
        service
            .register_diagnostic_resources(
                &[CicsDumpCodeDefinition {
                    code: "ABCD".into(),
                    suppress: false,
                    maximum: 1,
                    system_dump: false,
                }],
                &[],
            )
            .unwrap();
        let (invocation, _) = registered(&service);
        let arguments = BTreeMap::from([
            ("DUMPCODE".into(), cics_literal(b"ABCD")),
            ("FROM".into(), enqueue_value(b"ABCDEFG")),
            ("FLENGTH".into(), cics_decimal(3)),
            ("OPTION.TASK".into(), cics_option()),
            (
                "DUMPID".into(),
                BoundedPayload::new(
                    "mainframe-env.cics.argument@1",
                    b"DUMP-ID-X".to_vec(),
                    InvocationLimits::default(),
                )
                .unwrap(),
            ),
        ]);
        let dump = request(CicsOperation::DumpTransaction, arguments.clone(), 1);
        let first = service
            .invoke(
                &effect(&invocation.run_unit_id, dump.clone(), 1),
                dump.clone(),
            )
            .unwrap();
        assert_eq!(first.condition, "NORMAL");
        assert_eq!(first.outputs["DUMPID"].bytes(), b"1/0001");
        let snapshot = service.diagnostic_snapshot().unwrap();
        assert_eq!(snapshot.dumps.len(), 1);
        assert_eq!(snapshot.dumps[0].dump_id, "1/0001");
        assert_eq!(snapshot.dumps[0].sections, ["DUMPCODE", "TASK", "FROM"]);
        assert!(
            snapshot.dumps[0]
                .data
                .windows(3)
                .any(|bytes| bytes == b"ABC")
        );
        store
            .delete_provider_state("cics-effect-replay-v1", "outer-1", 1)
            .unwrap();
        let replayed = service
            .invoke(&effect(&invocation.run_unit_id, dump.clone(), 1), dump)
            .unwrap();
        assert_eq!(replayed, first);
        assert_eq!(service.diagnostic_snapshot().unwrap().dumps.len(), 1);

        let mut suppressed = request(CicsOperation::DumpTransaction, arguments, 2);
        suppressed.condition_policy = CicsConditionPolicy::NoHandle;
        let result = service
            .invoke(
                &effect(&invocation.run_unit_id, suppressed.clone(), 2),
                suppressed,
            )
            .unwrap();
        assert_eq!(
            (result.condition.as_str(), result.response, result.response2),
            ("SUPPRESSED", 72, 1)
        );
        assert_eq!(service.diagnostic_snapshot().unwrap().dumps.len(), 1);

        let mut invalid = request(
            CicsOperation::DumpTransaction,
            BTreeMap::from([("DUMPCODE".into(), cics_literal(b"A B"))]),
            3,
        );
        invalid.condition_policy = CicsConditionPolicy::NoHandle;
        let result = service
            .invoke(
                &effect(&invocation.run_unit_id, invalid.clone(), 3),
                invalid,
            )
            .unwrap();
        assert_eq!(
            (result.condition.as_str(), result.response, result.response2),
            ("INVREQ", 16, 13)
        );
        assert_eq!(service.diagnostic_snapshot().unwrap().dumps.len(), 2);
    }

    #[test]
    fn dump_transaction_segments_and_counter_survive_sqlite_reopen() {
        let root = std::env::temp_dir().join(format!(
            "mainframe-env-cics-dump-transaction-{}-{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&root).unwrap();
        let url = format!("sqlite://{}?mode=rwc", root.join("state.db").display());
        {
            let store = Arc::new(SqliteStateStore::open(&url, 4 * 1024 * 1024, 65_536).unwrap());
            let service = service(store);
            let (invocation, _) = registered(&service);
            let dump = request(
                CicsOperation::DumpTransaction,
                BTreeMap::from([("DUMPCODE".into(), cics_literal(b"ABCD"))]),
                1,
            );
            service
                .invoke(&effect(&invocation.run_unit_id, dump.clone(), 1), dump)
                .unwrap();
        }
        {
            let store = Arc::new(SqliteStateStore::open(&url, 4 * 1024 * 1024, 65_536).unwrap());
            let service = service(store);
            let invocation = invocation_for("dump-reopen", BTreeMap::new());
            let session = SessionId::new("dump-reopen", 64).unwrap();
            service.create_session(&session, 24, 80).unwrap();
            service
                .register_run(invocation.clone(), &session, "MENU", "MEAPPL", "MESYS")
                .unwrap();
            let dump = request(
                CicsOperation::DumpTransaction,
                BTreeMap::from([
                    ("DUMPCODE".into(), cics_literal(b"EFGH")),
                    ("SEGMENTLIST".into(), enqueue_value(&[0, 0, 0, 1])),
                    ("LENGTHLIST".into(), enqueue_value(&[0, 0, 0, 3])),
                    ("NUMSEGMENTS".into(), cics_decimal(1)),
                    (
                        "SEGMENTS".into(),
                        BoundedPayload::new(
                            "mainframe-env.cics.dump-segments@1",
                            b"\0\0\0\x03XYZ".to_vec(),
                            InvocationLimits::default(),
                        )
                        .unwrap(),
                    ),
                ]),
                2,
            );
            service
                .invoke(&effect(&invocation.run_unit_id, dump.clone(), 2), dump)
                .unwrap();
            let snapshot = service.diagnostic_snapshot().unwrap();
            assert_eq!(snapshot.dumps.len(), 2);
            assert_eq!(snapshot.dumps[1].dump_id, "2/0001");
            assert!(snapshot.dumps[1].sections.contains(&"SEGMENT0001".into()));
            assert!(
                snapshot.dumps[1]
                    .data
                    .windows(3)
                    .any(|bytes| bytes == b"XYZ")
            );
        }
        std::fs::remove_dir_all(root).unwrap();
    }

