    #[test]
    fn freemain_returns_release_intent_and_exact_invalid_pointer_condition() {
        let service = service(Arc::new(MemoryStore::new(Default::default())));
        let (invocation, _) = registered(&service);
        let pointer = |schema: &str, bytes: &[u8]| {
            BoundedPayload::new(schema, bytes.to_vec(), InvocationLimits::default()).unwrap()
        };
        let valid = request(
            CicsOperation::Freemain,
            BTreeMap::from([(
                "DATAPOINTER".into(),
                pointer(
                    "mainframe-env.cics.allocated-pointer@1",
                    &[0, 0, 0, 2, 0, 0, 0, 0],
                ),
            )]),
            1,
        );
        let response = service
            .invoke(
                &effect(&invocation.run_unit_id, valid.clone(), 1),
                valid.clone(),
            )
            .unwrap();
        assert_eq!(
            (response.condition.as_str(), response.response),
            ("NORMAL", 0)
        );
        assert_eq!(
            response.outputs["FREEMAIN.POINTER"],
            valid.arguments["DATAPOINTER"]
        );
        let replay = service
            .invoke(&effect(&invocation.run_unit_id, valid.clone(), 1), valid)
            .unwrap();
        assert_eq!(replay, response);

        let data = request(
            CicsOperation::Freemain,
            BTreeMap::from([(
                "DATA".into(),
                pointer(
                    "mainframe-env.cics.allocated-pointer@1",
                    &[0, 0, 0, 3, 0, 0, 0, 0],
                ),
            )]),
            2,
        );
        let response = service
            .invoke(
                &effect(&invocation.run_unit_id, data.clone(), 2),
                data.clone(),
            )
            .unwrap();
        assert_eq!(
            (response.condition.as_str(), response.response),
            ("NORMAL", 0)
        );
        assert_eq!(response.outputs["FREEMAIN.POINTER"], data.arguments["DATA"]);

        let both = request(
            CicsOperation::Freemain,
            BTreeMap::from([
                (
                    "DATA".into(),
                    pointer("mainframe-env.cics.allocated-pointer@1", &[0; 8]),
                ),
                (
                    "DATAPOINTER".into(),
                    pointer("mainframe-env.cics.allocated-pointer@1", &[0; 8]),
                ),
            ]),
            3,
        );
        assert_eq!(
            service.invoke(&effect(&invocation.run_unit_id, both.clone(), 3), both),
            Err(HostProblem::Malformed)
        );

        let mut invalid = request(
            CicsOperation::Freemain,
            BTreeMap::from([
                (
                    "DATAPOINTER".into(),
                    pointer("mainframe-env.cics.invalid-pointer@1", &[0; 8]),
                ),
                ("RESP".into(), argument(b"RESP-X")),
                ("RESP2".into(), argument(b"RESP2-X")),
            ]),
            4,
        );
        invalid.condition_policy = CicsConditionPolicy::Respond {
            response_field: "RESP-X".into(),
            response2_field: Some("RESP2-X".into()),
        };
        let invalid = service
            .invoke(
                &effect(&invocation.run_unit_id, invalid.clone(), 4),
                invalid,
            )
            .unwrap();
        assert_eq!(
            (
                invalid.condition.as_str(),
                invalid.response,
                invalid.response2
            ),
            ("INVREQ", 16, 1)
        );
        assert!(!invalid.outputs.contains_key("FREEMAIN.POINTER"));
    }

    #[test]
    fn freemain64_releases_only_a_checked_64_bit_identity_with_exact_conditions() {
        let service = service(Arc::new(MemoryStore::new(Default::default())));
        let (invocation, _) = registered_amode64(&service);
        let pointer = |schema: &str| {
            BoundedPayload::new(
                schema,
                vec![0xA0, 0, 0, 1, 0, 0, 0, 8],
                InvocationLimits::default(),
            )
            .unwrap()
        };
        let abi = || cics_literal(b"mainframe-env.cics-amode64-nonle@1");
        let valid = request(
            CicsOperation::Freemain64,
            BTreeMap::from([
                ("ABI64".into(), abi()),
                (
                    "DATAPOINTER".into(),
                    pointer("mainframe-env.cics.allocated-pointer64@1"),
                ),
            ]),
            1,
        );
        let first = service
            .invoke(
                &effect(&invocation.run_unit_id, valid.clone(), 1),
                valid.clone(),
            )
            .unwrap();
        assert_eq!((first.condition.as_str(), first.response), ("NORMAL", 0));
        assert_eq!(
            first.outputs["FREEMAIN64.POINTER"],
            valid.arguments["DATAPOINTER"]
        );
        assert_eq!(
            service
                .invoke(&effect(&invocation.run_unit_id, valid.clone(), 1), valid)
                .unwrap(),
            first
        );
        let data = request(
            CicsOperation::Freemain64,
            BTreeMap::from([
                ("ABI64".into(), abi()),
                (
                    "DATA".into(),
                    pointer("mainframe-env.cics.allocated-pointer64@1"),
                ),
            ]),
            2,
        );
        let data = service
            .invoke(&effect(&invocation.run_unit_id, data.clone(), 2), data)
            .unwrap();
        assert_eq!(data.response, 0);

        for (sequence, schema, expected) in [
            (3, "mainframe-env.cics.invalid-pointer64@1", 1),
            (4, "mainframe-env.cics.key-violation64@1", 2),
        ] {
            let mut invalid = request(
                CicsOperation::Freemain64,
                BTreeMap::from([
                    ("ABI64".into(), abi()),
                    ("DATAPOINTER".into(), pointer(schema)),
                ]),
                sequence,
            );
            invalid.condition_policy = CicsConditionPolicy::Respond {
                response_field: "RESP-X".into(),
                response2_field: Some("RESP2-X".into()),
            };
            let response = service
                .invoke(
                    &effect(&invocation.run_unit_id, invalid.clone(), sequence),
                    invalid,
                )
                .unwrap();
            assert_eq!(
                (
                    response.condition.as_str(),
                    response.response,
                    response.response2
                ),
                ("INVREQ", 16, expected)
            );
            assert!(!response.outputs.contains_key("FREEMAIN64.POINTER"));
        }
    }

