    #[test]
    fn unlock_no_hold_reports_file_status_conditions_exactly() {
        let service = service(Arc::new(MemoryStore::new(Default::default())));
        let (invocation, _) = registered(&service);
        service
            .register_file_aliases(&BTreeMap::from([(
                "ACCTDAT".into(),
                DatasetName::new("CARDDEMO.ACCTDAT", 128).unwrap(),
            )]))
            .unwrap();
        let unknown = request(
            CicsOperation::Unlock,
            BTreeMap::from([("FILE".into(), argument(b"UNKNOWN"))]),
            1,
        );
        assert_eq!(
            service.invoke(
                &effect(&invocation.run_unit_id, unknown.clone(), 1),
                unknown
            ),
            Err(HostProblem::Condition {
                name: "FILENOTFOUND".into(),
                response: 12,
                response2: 1
            })
        );
        for (sequence, status, expected) in [
            (2, b"DISABLED".as_slice(), ("DISABLED", 84, 50)),
            (4, b"CLOSED".as_slice(), ("NOTOPEN", 19, 60)),
        ] {
            let value = BoundedPayload::new(
                "mainframe-env.cics.file-status@1",
                status.to_vec(),
                InvocationLimits::default(),
            )
            .unwrap();
            let set = request(
                CicsOperation::SetFileStatus,
                BTreeMap::from([("ACCTDAT".into(), value)]),
                sequence,
            );
            service
                .invoke(&effect(&invocation.run_unit_id, set.clone(), sequence), set)
                .unwrap();
            let unlock = request(
                CicsOperation::Unlock,
                BTreeMap::from([("FILE".into(), argument(b"ACCTDAT"))]),
                sequence + 1,
            );
            assert_eq!(
                service.invoke(
                    &effect(&invocation.run_unit_id, unlock.clone(), sequence + 1),
                    unlock
                ),
                Err(HostProblem::Condition {
                    name: expected.0.into(),
                    response: expected.1,
                    response2: expected.2,
                })
            );
        }
        let remote = request(
            CicsOperation::Unlock,
            BTreeMap::from([
                ("FILE".into(), argument(b"ACCTDAT")),
                ("SYSID".into(), argument(b"REMOTE")),
            ]),
            6,
        );
        assert_eq!(
            service.invoke(&effect(&invocation.run_unit_id, remote.clone(), 6), remote),
            Err(HostProblem::Condition {
                name: "SYSIDERR".into(),
                response: 53,
                response2: 130,
            })
        );
    }

    #[test]
    fn token_rewrite_and_delete_consume_only_their_read_update_token() {
        let trace = Arc::new(DatasetTrace::default());
        let store: Arc<dyn ProviderStateStore> = Arc::new(MemoryStore::new(Default::default()));
        let service =
            CicsService::open(traced_authorities(trace.clone()), store, Default::default())
                .unwrap();
        let (invocation, _) = registered(&service);
        service
            .register_file_aliases(&BTreeMap::from([(
                "ACCTDAT".into(),
                DatasetName::new("CARDDEMO.ACCTDAT", 128).unwrap(),
            )]))
            .unwrap();
        let read_token = |sequence| {
            let read = request(
                CicsOperation::Read,
                BTreeMap::from([
                    ("FILE".into(), argument(b"ACCTDAT")),
                    ("RIDFLD".into(), argument(b"AA")),
                    ("TOKEN".into(), argument(b"TOKEN-X")),
                ]),
                sequence,
            );
            let response = service
                .invoke(
                    &effect(&invocation.run_unit_id, read.clone(), sequence),
                    read,
                )
                .unwrap();
            std::str::from_utf8(response.outputs["TOKEN"].bytes())
                .unwrap()
                .parse::<i64>()
                .unwrap()
        };
        let first = read_token(1);
        let rewrite = request(
            CicsOperation::Rewrite,
            BTreeMap::from([
                ("FILE".into(), argument(b"ACCTDAT")),
                ("FROM".into(), argument(b"AA22")),
                ("TOKEN".into(), cics_decimal(first)),
            ]),
            2,
        );
        service
            .invoke(
                &effect(&invocation.run_unit_id, rewrite.clone(), 2),
                rewrite,
            )
            .unwrap();
        let second = read_token(3);
        let delete = request(
            CicsOperation::Delete,
            BTreeMap::from([
                ("FILE".into(), argument(b"ACCTDAT")),
                ("TOKEN".into(), cics_decimal(second)),
            ]),
            4,
        );
        service
            .invoke(&effect(&invocation.run_unit_id, delete.clone(), 4), delete)
            .unwrap();
        assert!(second > first);
        let third = read_token(5);
        let syncpoint = request(CicsOperation::Syncpoint, BTreeMap::new(), 6);
        service
            .invoke(
                &effect(&invocation.run_unit_id, syncpoint.clone(), 6),
                syncpoint,
            )
            .unwrap();
        let stale = request(
            CicsOperation::Unlock,
            BTreeMap::from([
                ("FILE".into(), argument(b"ACCTDAT")),
                ("TOKEN".into(), cics_decimal(third)),
            ]),
            7,
        );
        assert_eq!(
            service.invoke(&effect(&invocation.run_unit_id, stale.clone(), 7), stale),
            Err(HostProblem::Condition {
                name: "INVREQ".into(),
                response: 16,
                response2: 47,
            })
        );
        let requests = trace.requests.lock().unwrap();
        assert!(requests.iter().any(|request| matches!(request,
            DatasetRequest::RewriteRecord { key, record, .. } if key == b"AA" && record == b"AA22"
        )));
        assert!(requests.iter().any(|request| matches!(request,
            DatasetRequest::DeleteRecord { key, .. } if key == b"AA"
        )));
    }

    #[test]
    fn browse_token_is_invalidated_by_reset_and_following_read_without_losing_cursor() {
        let trace = Arc::new(DatasetTrace::default());
        let store: Arc<dyn ProviderStateStore> = Arc::new(MemoryStore::new(Default::default()));
        let service =
            CicsService::open(traced_authorities(trace.clone()), store, Default::default())
                .unwrap();
        let (invocation, _) = registered(&service);
        service
            .register_file_aliases(&BTreeMap::from([(
                "ACCTDAT".into(),
                DatasetName::new("CARDDEMO.ACCTDAT", 128).unwrap(),
            )]))
            .unwrap();
        let file = || ("FILE".into(), argument(b"ACCTDAT"));
        let start = request(
            CicsOperation::StartBrowse,
            BTreeMap::from([file(), ("RIDFLD".into(), argument(b"AA"))]),
            1,
        );
        service
            .invoke(&effect(&invocation.run_unit_id, start.clone(), 1), start)
            .unwrap();
        let read_token = |sequence| {
            let read = request(
                CicsOperation::ReadNext,
                BTreeMap::from([file(), ("TOKEN".into(), argument(b"TOKEN-X"))]),
                sequence,
            );
            let response = service
                .invoke(
                    &effect(&invocation.run_unit_id, read.clone(), sequence),
                    read,
                )
                .unwrap();
            std::str::from_utf8(response.outputs["TOKEN"].bytes())
                .unwrap()
                .parse::<i64>()
                .unwrap()
        };
        let first = read_token(2);
        let reset = request(
            CicsOperation::ResetBrowse,
            BTreeMap::from([
                file(),
                ("RIDFLD".into(), argument(b"AA")),
                ("OPTION.GTEQ".into(), cics_option()),
            ]),
            3,
        );
        service
            .invoke(&effect(&invocation.run_unit_id, reset.clone(), 3), reset)
            .unwrap();
        let invalid = request(
            CicsOperation::Unlock,
            BTreeMap::from([file(), ("TOKEN".into(), cics_decimal(first))]),
            4,
        );
        assert_eq!(
            service.invoke(
                &effect(&invocation.run_unit_id, invalid.clone(), 4),
                invalid
            ),
            Err(HostProblem::Condition {
                name: "INVREQ".into(),
                response: 16,
                response2: 47
            })
        );
        let second = read_token(5);
        let next = request(CicsOperation::ReadNext, BTreeMap::from([file()]), 6);
        service
            .invoke(&effect(&invocation.run_unit_id, next.clone(), 6), next)
            .unwrap();
        let invalid = request(
            CicsOperation::Unlock,
            BTreeMap::from([file(), ("TOKEN".into(), cics_decimal(second))]),
            7,
        );
        assert_eq!(
            service.invoke(
                &effect(&invocation.run_unit_id, invalid.clone(), 7),
                invalid
            ),
            Err(HostProblem::Condition {
                name: "INVREQ".into(),
                response: 16,
                response2: 47
            })
        );
        let third = read_token(8);
        let unlock = request(
            CicsOperation::Unlock,
            BTreeMap::from([file(), ("TOKEN".into(), cics_decimal(third))]),
            9,
        );
        assert_eq!(
            service
                .invoke(&effect(&invocation.run_unit_id, unlock.clone(), 9), unlock)
                .unwrap()
                .condition,
            "NORMAL"
        );
        let next = request(CicsOperation::ReadNext, BTreeMap::from([file()]), 10);
        service
            .invoke(&effect(&invocation.run_unit_id, next.clone(), 10), next)
            .unwrap();
        assert!(
            trace
                .requests
                .lock()
                .unwrap()
                .iter()
                .filter(|request| matches!(request,
                    DatasetRequest::ReadNext { cursor, .. } if cursor == "CURSOR-1"
                ))
                .count()
                >= 5
        );
    }

    #[test]
    fn unlock_token_counter_survives_sqlite_reopen_without_reusing_a_stale_token() {
        let directory = std::env::temp_dir().join(format!(
            "mainframe-env-unlock-token-{}-{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&directory).unwrap();
        let path = directory.join("cics.db");
        let url = format!("sqlite://{}?mode=rwc", path.display());
        let trace = Arc::new(DatasetTrace::default());
        let token = {
            let store: Arc<dyn ProviderStateStore> =
                Arc::new(SqliteStateStore::open(&url, 4 * 1024 * 1024, 65_536).unwrap());
            let service =
                CicsService::open(traced_authorities(trace.clone()), store, Default::default())
                    .unwrap();
            let (invocation, _) = registered(&service);
            service
                .register_file_aliases(&BTreeMap::from([(
                    "ACCTDAT".into(),
                    DatasetName::new("CARDDEMO.ACCTDAT", 128).unwrap(),
                )]))
                .unwrap();
            let read = request(
                CicsOperation::Read,
                BTreeMap::from([
                    ("FILE".into(), argument(b"ACCTDAT")),
                    ("RIDFLD".into(), argument(b"AA")),
                    ("TOKEN".into(), argument(b"TOKEN-X")),
                ]),
                1,
            );
            let response = service
                .invoke(&effect(&invocation.run_unit_id, read.clone(), 1), read)
                .unwrap();
            std::str::from_utf8(response.outputs["TOKEN"].bytes())
                .unwrap()
                .parse::<i64>()
                .unwrap()
        };
        {
            let store: Arc<dyn ProviderStateStore> =
                Arc::new(SqliteStateStore::open(&url, 4 * 1024 * 1024, 65_536).unwrap());
            let service =
                CicsService::open(traced_authorities(trace), store, Default::default()).unwrap();
            let invocation = invocation_for("unlock-sqlite-reopen", BTreeMap::new());
            let session = SessionId::new("unlock-sqlite-session", 64).unwrap();
            service.create_session(&session, 24, 80).unwrap();
            service
                .register_run(invocation.clone(), &session, "MENU", "MEAPPL", "MESYS")
                .unwrap();
            let read = request(
                CicsOperation::Read,
                BTreeMap::from([
                    ("FILE".into(), argument(b"ACCTDAT")),
                    ("RIDFLD".into(), argument(b"AA")),
                    ("TOKEN".into(), argument(b"TOKEN-X")),
                ]),
                20,
            );
            let response = service
                .invoke(&effect(&invocation.run_unit_id, read.clone(), 20), read)
                .unwrap();
            let next = std::str::from_utf8(response.outputs["TOKEN"].bytes())
                .unwrap()
                .parse::<i64>()
                .unwrap();
            assert_eq!(next, token + 1);
            let stale = request(
                CicsOperation::Unlock,
                BTreeMap::from([
                    ("FILE".into(), argument(b"ACCTDAT")),
                    ("TOKEN".into(), cics_decimal(token)),
                ]),
                21,
            );
            assert_eq!(
                service.invoke(&effect(&invocation.run_unit_id, stale.clone(), 21), stale),
                Err(HostProblem::Condition {
                    name: "INVREQ".into(),
                    response: 16,
                    response2: 47
                })
            );
        }
        let _ = std::fs::remove_file(path);
        let _ = std::fs::remove_dir(directory);
    }

    #[cfg(feature = "fault-injection")]
    #[test]
    fn token_read_unknown_outcome_replays_one_held_token() {
        let trace = Arc::new(DatasetTrace::default());
        let store: Arc<dyn ProviderStateStore> = Arc::new(MemoryStore::new(Default::default()));
        let service =
            CicsService::open(traced_authorities(trace.clone()), store, Default::default())
                .unwrap();
        let (invocation, _) = registered(&service);
        service
            .register_file_aliases(&BTreeMap::from([(
                "ACCTDAT".into(),
                DatasetName::new("CARDDEMO.ACCTDAT", 128).unwrap(),
            )]))
            .unwrap();
        service.inject_replay_unknown_after_persist_once();
        let read = request(
            CicsOperation::Read,
            BTreeMap::from([
                ("FILE".into(), argument(b"ACCTDAT")),
                ("RIDFLD".into(), argument(b"AA")),
                ("TOKEN".into(), argument(b"TOKEN-X")),
            ]),
            1,
        );
        assert_eq!(
            service.invoke(
                &effect(&invocation.run_unit_id, read.clone(), 1),
                read.clone()
            ),
            Err(HostProblem::UnknownOutcome)
        );
        let replay = service
            .invoke(&effect(&invocation.run_unit_id, read.clone(), 1), read)
            .unwrap();
        assert_eq!(replay.outputs["TOKEN"].bytes(), b"1");
        assert_eq!(trace.requests.lock().unwrap().len(), 1);
        let unlock = request(
            CicsOperation::Unlock,
            BTreeMap::from([
                ("FILE".into(), argument(b"ACCTDAT")),
                ("TOKEN".into(), cics_decimal(1)),
            ]),
            2,
        );
        service.inject_replay_unknown_after_persist_once();
        assert_eq!(
            service.invoke(
                &effect(&invocation.run_unit_id, unlock.clone(), 2),
                unlock.clone()
            ),
            Err(HostProblem::UnknownOutcome)
        );
        assert_eq!(
            service
                .invoke(&effect(&invocation.run_unit_id, unlock.clone(), 2), unlock)
                .unwrap()
                .condition,
            "NORMAL"
        );
        let repeated = request(
            CicsOperation::Unlock,
            BTreeMap::from([
                ("FILE".into(), argument(b"ACCTDAT")),
                ("TOKEN".into(), cics_decimal(1)),
            ]),
            3,
        );
        assert_eq!(
            service.invoke(
                &effect(&invocation.run_unit_id, repeated.clone(), 3),
                repeated
            ),
            Err(HostProblem::Condition {
                name: "INVREQ".into(),
                response: 16,
                response2: 47
            })
        );
    }

    #[test]
    fn start_browse_generic_key_length_selects_prefix_and_first_record() {
        let trace = Arc::new(DatasetTrace::default());
        let store: Arc<dyn ProviderStateStore> = Arc::new(MemoryStore::new(Default::default()));
        let service =
            CicsService::open(traced_authorities(trace.clone()), store, Default::default())
                .unwrap();
        let (invocation, _) = registered(&service);
        service
            .register_file_aliases(&BTreeMap::from([(
                "CARDDAT".into(),
                DatasetName::new("CARDDEMO.CARDDAT", 128).unwrap(),
            )]))
            .unwrap();

        let generic_equal = request(
            CicsOperation::StartBrowse,
            BTreeMap::from([
                ("FILE".into(), argument(b"CARDDAT")),
                ("RIDFLD".into(), argument(b"AAZ")),
                ("KEYLENGTH".into(), cics_decimal(2)),
                ("OPTION.GENERIC".into(), cics_option()),
                ("OPTION.EQUAL".into(), cics_option()),
            ]),
            1,
        );
        service
            .invoke(
                &effect(&invocation.run_unit_id, generic_equal.clone(), 1),
                generic_equal,
            )
            .unwrap();
        let end = request(
            CicsOperation::EndBrowse,
            BTreeMap::from([("FILE".into(), argument(b"CARDDAT"))]),
            2,
        );
        service
            .invoke(&effect(&invocation.run_unit_id, end.clone(), 2), end)
            .unwrap();

        let missing_prefix = request(
            CicsOperation::StartBrowse,
            BTreeMap::from([
                ("FILE".into(), argument(b"CARDDAT")),
                ("RIDFLD".into(), argument(b"BBZ")),
                ("KEYLENGTH".into(), cics_decimal(2)),
                ("OPTION.GENERIC".into(), cics_option()),
                ("OPTION.EQUAL".into(), cics_option()),
            ]),
            3,
        );
        assert_eq!(
            service.invoke(
                &effect(&invocation.run_unit_id, missing_prefix.clone(), 3),
                missing_prefix,
            ),
            Err(HostProblem::Condition {
                name: "NOTFND".into(),
                response: 13,
                response2: 80,
            })
        );

        let first = request(
            CicsOperation::StartBrowse,
            BTreeMap::from([
                ("FILE".into(), argument(b"CARDDAT")),
                ("RIDFLD".into(), argument(b"ZZ")),
                ("KEYLENGTH".into(), cics_decimal(0)),
                ("OPTION.GENERIC".into(), cics_option()),
                ("OPTION.GTEQ".into(), cics_option()),
            ]),
            4,
        );
        service
            .invoke(&effect(&invocation.run_unit_id, first.clone(), 4), first)
            .unwrap();

        for (sequence, key_length, generic, response2) in
            [(5, 1, false, 26), (6, 3, true, 25), (7, -1, true, 42)]
        {
            let mut arguments = BTreeMap::from([
                ("FILE".into(), argument(b"CARDDAT")),
                ("RIDFLD".into(), argument(b"AAZ")),
                ("KEYLENGTH".into(), cics_decimal(key_length)),
            ]);
            if generic {
                arguments.insert("OPTION.GENERIC".into(), cics_option());
                arguments.insert("OPTION.EQUAL".into(), cics_option());
            }
            let invalid = request(CicsOperation::StartBrowse, arguments, sequence);
            assert_eq!(
                service.invoke(
                    &effect(&invocation.run_unit_id, invalid.clone(), sequence),
                    invalid,
                ),
                Err(HostProblem::Condition {
                    name: "INVREQ".into(),
                    response: 16,
                    response2,
                })
            );
        }

        let requests = trace.requests.lock().unwrap();
        assert!(matches!(requests[0], DatasetRequest::Attributes { .. }));
        assert!(matches!(
            &requests[1],
            DatasetRequest::StartBrowse { key, relation, .. }
                if key == b"AA" && *relation == mainframe_env_host_api::KeyRelation::GreaterOrEqual
        ));
        assert!(matches!(requests[2], DatasetRequest::ReadNext { .. }));
        assert!(matches!(requests[3], DatasetRequest::EndBrowse { .. }));
        assert!(matches!(
            &requests[4],
            DatasetRequest::StartBrowse { key, relation, .. }
                if key == b"AA" && *relation == mainframe_env_host_api::KeyRelation::GreaterOrEqual
        ));
        assert!(matches!(
            &requests[11],
            DatasetRequest::StartBrowse { key, relation, .. }
                if key.is_empty()
                    && *relation == mainframe_env_host_api::KeyRelation::GreaterOrEqual
        ));
    }

    #[test]
    fn browse_length_truncates_and_returns_actual_record_length() {
        let trace = Arc::new(DatasetTrace::default());
        let store: Arc<dyn ProviderStateStore> = Arc::new(MemoryStore::new(Default::default()));
        let service =
            CicsService::open(traced_authorities(trace.clone()), store, Default::default())
                .unwrap();
        let (invocation, _) = registered(&service);
        service
            .register_file_aliases(&BTreeMap::from([(
                "CARDDAT".into(),
                DatasetName::new("CARDDEMO.CARDDAT", 128).unwrap(),
            )]))
            .unwrap();

        let start = request(
            CicsOperation::StartBrowse,
            BTreeMap::from([
                ("FILE".into(), argument(b"CARDDAT")),
                ("RIDFLD".into(), argument(b"AA")),
            ]),
            1,
        );
        service
            .invoke(&effect(&invocation.run_unit_id, start.clone(), 1), start)
            .unwrap();

        let next = request(
            CicsOperation::ReadNext,
            BTreeMap::from([
                ("FILE".into(), argument(b"CARDDAT")),
                ("LENGTH".into(), cics_decimal(2)),
            ]),
            2,
        );
        let truncated = service
            .invoke(&effect(&invocation.run_unit_id, next.clone(), 2), next)
            .unwrap();
        assert_eq!(truncated.condition, "LENGERR");
        assert_eq!((truncated.response, truncated.response2), (22, 11));
        assert_eq!(truncated.payload.bytes(), b"AA");
        assert_eq!(truncated.outputs["LENGTH"].bytes(), b"4");

        let previous = request(
            CicsOperation::ReadPrev,
            BTreeMap::from([
                ("FILE".into(), argument(b"CARDDAT")),
                ("LENGTH".into(), cics_decimal(6)),
            ]),
            3,
        );
        let fixed_mismatch = service
            .invoke(
                &effect(&invocation.run_unit_id, previous.clone(), 3),
                previous,
            )
            .unwrap();
        assert_eq!(fixed_mismatch.condition, "LENGERR");
        assert_eq!(
            (fixed_mismatch.response, fixed_mismatch.response2),
            (22, 13)
        );
        assert_eq!(fixed_mismatch.payload.bytes(), b"AA11");
        assert_eq!(fixed_mismatch.outputs["LENGTH"].bytes(), b"4");

        let requests = trace.requests.lock().unwrap();
        assert!(matches!(requests[0], DatasetRequest::StartBrowse { .. }));
        assert!(matches!(requests[1], DatasetRequest::Attributes { .. }));
        assert!(matches!(
            requests[2],
            DatasetRequest::ReadNext { reverse: false, .. }
        ));
        assert!(matches!(requests[3], DatasetRequest::Attributes { .. }));
        assert!(matches!(
            requests[4],
            DatasetRequest::ReadNext { reverse: true, .. }
        ));
    }

    /// Issue #205: current-record DELETE consumes exactly one READ UPDATE hold.
    #[test]
    fn delete_without_ridfld_uses_and_releases_latest_read_update_hold() {
        let trace = Arc::new(DatasetTrace::default());
        let store: Arc<dyn ProviderStateStore> = Arc::new(MemoryStore::new(Default::default()));
        let service =
            CicsService::open(traced_authorities(trace.clone()), store, Default::default())
                .unwrap();
        let (invocation, _) = registered(&service);
        service
            .register_file_aliases(&BTreeMap::from([(
                "ACCTDAT".into(),
                DatasetName::new("CARDDEMO.ACCTDAT", 128).unwrap(),
            )]))
            .unwrap();
        let read = request(
            CicsOperation::Read,
            BTreeMap::from([
                ("FILE".into(), argument(b"ACCTDAT")),
                ("RIDFLD".into(), argument(b"AA")),
                ("OPTION.UPDATE".into(), argument(b"")),
            ]),
            1,
        );
        service
            .invoke(&effect(&invocation.run_unit_id, read.clone(), 1), read)
            .unwrap();
        let delete = request(
            CicsOperation::Delete,
            BTreeMap::from([("FILE".into(), argument(b"ACCTDAT"))]),
            2,
        );
        service
            .invoke(&effect(&invocation.run_unit_id, delete.clone(), 2), delete)
            .unwrap();

        let second = request(
            CicsOperation::Delete,
            BTreeMap::from([("FILE".into(), argument(b"ACCTDAT"))]),
            3,
        );
        assert_eq!(
            service.invoke(&effect(&invocation.run_unit_id, second.clone(), 3), second),
            Err(HostProblem::Condition {
                name: "INVREQ".into(),
                response: 16,
                response2: 31,
            })
        );
        assert!(matches!(
            trace.requests.lock().unwrap().as_slice(),
            [
                DatasetRequest::Read { .. },
                DatasetRequest::DeleteRecord { key, .. }
            ] if key == b"AA"
        ));
    }

    #[test]
    fn syncpoint_rollback_compensates_reached_dataset_rewrite() {
        let trace = Arc::new(DatasetTrace::default());
        let store: Arc<dyn ProviderStateStore> = Arc::new(MemoryStore::new(Default::default()));
        let service =
            CicsService::open(traced_authorities(trace.clone()), store, Default::default())
                .unwrap();
        let (invocation, _) = registered(&service);
        service
            .register_file_aliases(&BTreeMap::from([(
                "ACCTDAT".into(),
                DatasetName::new("CARDDEMO.ACCTDAT", 128).unwrap(),
            )]))
            .unwrap();
        let read = request(
            CicsOperation::Read,
            BTreeMap::from([
                ("DATASET".into(), argument(b"ACCTDAT")),
                ("RIDFLD".into(), argument(b"AA")),
                ("OPTION.UPDATE".into(), argument(b"")),
            ]),
            1,
        );
        service
            .invoke(&effect(&invocation.run_unit_id, read.clone(), 1), read)
            .unwrap();
        let rewrite = request(
            CicsOperation::Rewrite,
            BTreeMap::from([
                ("DATASET".into(), argument(b"ACCTDAT")),
                ("FROM".into(), argument(b"AA22")),
            ]),
            2,
        );
        service
            .invoke(
                &effect(&invocation.run_unit_id, rewrite.clone(), 2),
                rewrite,
            )
            .unwrap();
        let rollback = request(
            CicsOperation::Syncpoint,
            BTreeMap::from([("OPTION.ROLLBACK".into(), argument(b""))]),
            3,
        );
        assert_eq!(
            service
                .invoke(
                    &effect(&invocation.run_unit_id, rollback.clone(), 3),
                    rollback,
                )
                .unwrap()
                .unit_of_work,
            Some(CicsUnitOfWorkOutcome::RolledBack)
        );
        let requests = trace.requests.lock().unwrap();
        assert!(matches!(
            requests.as_slice(),
            [
                DatasetRequest::Read { .. },
                DatasetRequest::RewriteRecord { record, .. },
                DatasetRequest::RewriteRecord {
                    record: restored,
                    ..
                }
            ] if record == b"AA22" && restored == b"AA11"
        ));
    }

