    #[test]
    fn named_counter_define_is_durable_fenced_and_checks_bounds() {
        let store = Arc::new(MemoryStore::new(Default::default()));
        let cics = service(store.clone());
        let (invocation, _) = registered(&cics);
        let define = request(
            CicsOperation::DefineCounter,
            BTreeMap::from([
                ("COUNTER".into(), cics_literal(b"ORDERA")),
                ("POOL".into(), cics_literal(b"POOLA")),
                ("VALUE".into(), cics_decimal(5)),
                ("MINIMUM".into(), cics_decimal(5)),
                ("MAXIMUM".into(), cics_decimal(6)),
            ]),
            1,
        );
        let first = cics
            .invoke(
                &effect(&invocation.run_unit_id, define.clone(), 1),
                define.clone(),
            )
            .unwrap();
        assert_eq!(first.condition, "NORMAL");
        assert_eq!(
            cics.invoke(
                &effect(&invocation.run_unit_id, define.clone(), 1),
                define.clone()
            )
            .unwrap(),
            first
        );
        let duplicate = request(CicsOperation::DefineCounter, define.arguments.clone(), 2);
        assert_eq!(
            cics.invoke(
                &effect(&invocation.run_unit_id, duplicate.clone(), 2),
                duplicate
            ),
            Err(HostProblem::Condition {
                name: "INVREQ".into(),
                response: 16,
                response2: 202,
            })
        );
        let row = store
            .get_provider_state("cics-counter-control-v1", "state")
            .unwrap()
            .unwrap();
        let state: serde_json::Value = serde_json::from_slice(&row.payload).unwrap();
        assert_eq!(state["records"]["POOLA/ORDERA"]["current"], 5);
        let invalid = request(
            CicsOperation::DefineDCounter,
            BTreeMap::from([
                ("DCOUNTER".into(), cics_literal(b"ORDERB")),
                ("VALUE".into(), cics_decimal(2)),
                ("MINIMUM".into(), cics_decimal(3)),
            ]),
            3,
        );
        assert_eq!(
            cics.invoke(
                &effect(&invocation.run_unit_id, invalid.clone(), 3),
                invalid
            ),
            Err(HostProblem::Condition {
                name: "INVREQ".into(),
                response: 16,
                response2: 406,
            })
        );
    }

    #[test]
    fn named_counter_delete_is_atomic_and_replays() {
        let store = Arc::new(MemoryStore::new(Default::default()));
        let cics = service(store.clone());
        let (invocation, _) = registered(&cics);
        let args = BTreeMap::from([("DCOUNTER".into(), cics_literal(b"SEQUENCE"))]);
        let define = request(CicsOperation::DefineDCounter, args.clone(), 1);
        cics.invoke(&effect(&invocation.run_unit_id, define.clone(), 1), define)
            .unwrap();
        let delete = request(CicsOperation::DeleteDCounter, args, 2);
        let first = cics
            .invoke(
                &effect(&invocation.run_unit_id, delete.clone(), 2),
                delete.clone(),
            )
            .unwrap();
        assert_eq!(first.condition, "NORMAL");
        assert_eq!(
            cics.invoke(
                &effect(&invocation.run_unit_id, delete.clone(), 2),
                delete.clone()
            )
            .unwrap(),
            first
        );
        let absent = request(CicsOperation::DeleteDCounter, delete.arguments.clone(), 3);
        assert_eq!(
            cics.invoke(&effect(&invocation.run_unit_id, absent.clone(), 3), absent),
            Err(HostProblem::Condition {
                name: "INVREQ".into(),
                response: 16,
                response2: 201,
            })
        );
        let row = store
            .get_provider_state("cics-counter-control-v1", "state")
            .unwrap()
            .unwrap();
        let state: serde_json::Value = serde_json::from_slice(&row.payload).unwrap();
        assert!(state["records"].as_object().unwrap().is_empty());
    }

    #[test]
    fn named_counter_get_reserves_ranges_and_rewinds() {
        let cics = service(Arc::new(MemoryStore::new(Default::default())));
        let (invocation, _) = registered(&cics);
        let define = request(
            CicsOperation::DefineCounter,
            BTreeMap::from([
                ("COUNTER".into(), cics_literal(b"TICKET")),
                ("VALUE".into(), cics_decimal(1)),
                ("MAXIMUM".into(), cics_decimal(2)),
            ]),
            1,
        );
        cics.invoke(&effect(&invocation.run_unit_id, define.clone(), 1), define)
            .unwrap();
        let get_args = BTreeMap::from([
            ("COUNTER".into(), cics_literal(b"TICKET")),
            ("VALUE".into(), argument(b"")),
            ("INCREMENT".into(), cics_decimal(2)),
        ]);
        let get = request(CicsOperation::GetCounter, get_args.clone(), 2);
        let first = cics
            .invoke(
                &effect(&invocation.run_unit_id, get.clone(), 2),
                get.clone(),
            )
            .unwrap();
        assert_eq!(first.outputs["VALUE"].bytes(), b"1");
        assert_eq!(
            cics.invoke(&effect(&invocation.run_unit_id, get.clone(), 2), get)
                .unwrap(),
            first
        );
        let at_limit = request(CicsOperation::GetCounter, get_args.clone(), 3);
        assert_eq!(
            cics.invoke(
                &effect(&invocation.run_unit_id, at_limit.clone(), 3),
                at_limit
            ),
            Err(HostProblem::Condition {
                name: "SUPPRESSED".into(),
                response: 72,
                response2: 101,
            })
        );
        let wrapped = request(
            CicsOperation::GetCounter,
            BTreeMap::from([
                ("COUNTER".into(), cics_literal(b"TICKET")),
                ("VALUE".into(), argument(b"")),
                ("OPTION.WRAP".into(), cics_option()),
            ]),
            4,
        );
        let result = cics
            .invoke(
                &effect(&invocation.run_unit_id, wrapped.clone(), 4),
                wrapped,
            )
            .unwrap();
        assert_eq!(result.outputs["VALUE"].bytes(), b"0");
        let reduced = request(
            CicsOperation::GetCounter,
            BTreeMap::from([
                ("COUNTER".into(), cics_literal(b"TICKET")),
                ("VALUE".into(), argument(b"")),
                ("INCREMENT".into(), cics_decimal(3)),
                ("OPTION.REDUCE".into(), cics_option()),
            ]),
            5,
        );
        let result = cics
            .invoke(
                &effect(&invocation.run_unit_id, reduced.clone(), 5),
                reduced,
            )
            .unwrap();
        assert_eq!(result.outputs["VALUE"].bytes(), b"1");
    }

